-- Create "mail_jobs" table
CREATE TABLE "mail_jobs" ("id" uuid NOT NULL, "challenge_id" uuid NOT NULL, "provider" character varying NOT NULL, "generation" bigint NOT NULL, "template" character varying NOT NULL, "ciphertext" bytea NULL, "key_id" character varying NULL, "status" character varying NOT NULL DEFAULT 'pending', "attempts" bigint NOT NULL DEFAULT 0, "next_attempt_at" timestamptz NOT NULL, "lease_owner" character varying NULL, "lease_expires_at" timestamptz NULL, "result_class" character varying NOT NULL DEFAULT '', "expires_at" timestamptz NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "finished_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "mail_jobs_attempts" CHECK ((attempts >= 0) AND (attempts <= 3)), CONSTRAINT "mail_jobs_ciphertext" CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'sending'::character varying])::text[])) = ((ciphertext IS NOT NULL) AND (key_id IS NOT NULL))), CONSTRAINT "mail_jobs_expiry" CHECK (expires_at > created_at), CONSTRAINT "mail_jobs_finished" CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'sending'::character varying])::text[])) = (finished_at IS NULL)), CONSTRAINT "mail_jobs_generation" CHECK (generation >= 1), CONSTRAINT "mail_jobs_key_id" CHECK ((key_id IS NULL) OR ((char_length((key_id)::text) >= 1) AND (char_length((key_id)::text) <= 64))), CONSTRAINT "mail_jobs_lease" CHECK (((status)::text = 'sending'::text) = ((lease_owner IS NOT NULL) AND (lease_expires_at IS NOT NULL))), CONSTRAINT "mail_jobs_provider" CHECK ((provider)::text = ANY ((ARRAY['mailgun'::character varying, 'sendgrid'::character varying, 'smtp'::character varying, 'smtp2go'::character varying])::text[])), CONSTRAINT "mail_jobs_result" CHECK (char_length((result_class)::text) <= 64), CONSTRAINT "mail_jobs_status" CHECK ((status)::text = ANY ((ARRAY['pending'::character varying, 'sending'::character varying, 'accepted'::character varying, 'failed'::character varying, 'uncertain'::character varying, 'expired'::character varying, 'cancelled'::character varying])::text[])), CONSTRAINT "mail_jobs_template" CHECK ((template)::text = ANY ((ARRAY['verify_email'::character varying, 'reset_password'::character varying])::text[])));
-- Create index "mailjob_challenge_id" to table: "mail_jobs"
CREATE INDEX "mailjob_challenge_id" ON "mail_jobs" ("challenge_id");
-- Create index "mailjob_finished_at" to table: "mail_jobs"
CREATE INDEX "mailjob_finished_at" ON "mail_jobs" ("finished_at");
-- Create index "mailjob_status_lease_expires_at" to table: "mail_jobs"
CREATE INDEX "mailjob_status_lease_expires_at" ON "mail_jobs" ("status", "lease_expires_at");
-- Create index "mailjob_status_next_attempt_at" to table: "mail_jobs"
CREATE INDEX "mailjob_status_next_attempt_at" ON "mail_jobs" ("status", "next_attempt_at");
